mapper.select:
SELECT COUNT(*) FROM (


        SELECT 1 FROM docs_document
         WHERE object_id = #{objectId}
           AND (#{fileNo} = '*' OR EXISTS (
               SELECT 1 FROM docs_document_file f WHERE f.object_id = #{objectId} AND f.file_no = #{fileNo}
           )) LIMIT 1


        SELECT 1 FROM docs_drawing
         WHERE object_id = #{objectId}
           AND (#{fileNo} = '*' OR file_no::varchar = #{fileNo})
         LIMIT 1


        SELECT 1 FROM docs_sw
         WHERE object_id = #{objectId}
           AND (#{fileNo} = '*' OR EXISTS (
               SELECT 1 FROM docs_sw_file f WHERE f.object_id = #{objectId} AND f.file_no = #{fileNo}
           )) LIMIT 1


        SELECT 1 FROM docs_product_document
         WHERE object_id = #{objectId}
           AND (#{fileNo} = '*' OR EXISTS (
               SELECT 1 FROM docs_product_document_file f WHERE f.object_id = #{objectId} AND f.file_no = #{fileNo}
           )) LIMIT 1


        SELECT 1 FROM docs_product_sw
         WHERE object_id = #{objectId}
           AND (#{fileNo} = '*' OR EXISTS (
               SELECT 1 FROM docs_product_sw_file f WHERE f.object_id = #{objectId} AND f.file_no::varchar = #{fileNo}
           )) LIMIT 1


        SELECT 1 FROM docs_dxf_document
         WHERE object_id = #{objectId}
           AND (#{fileNo} = '*' OR EXISTS (
               SELECT 1 FROM docs_dxf_document_file f WHERE f.object_id = #{objectId} AND f.file_no = #{fileNo}
           )) LIMIT 1


        SELECT 1 FROM docs_document_sub_file
         WHERE parent_object_id = #{objectId}
           AND (#{fileNo} = '*' OR file_no::varchar = #{fileNo})
         LIMIT 1


        SELECT 1 FROM docs_drawing_sub_file
         WHERE parent_object_id = #{objectId}
           AND (#{fileNo} = '*' OR file_no::varchar = #{fileNo})
         LIMIT 1


        SELECT 1 FROM docs_sw_sub_file
         WHERE parent_object_id = #{objectId}
           AND (#{fileNo} = '*' OR file_no::varchar = #{fileNo})
         LIMIT 1


        SELECT 1
          FROM docs_production_sub_file f
         WHERE f.parent_object_id = #{objectId}
           AND (#{fileNo} = '*' OR f.file_no::varchar = #{fileNo})
           AND EXISTS (
               SELECT 1 FROM docs_product_document d WHERE d.object_id = f.parent_object_id
           )
         LIMIT 1


        SELECT 1
          FROM docs_production_sub_file f
         WHERE f.parent_object_id = #{objectId}
           AND (#{fileNo} = '*' OR f.file_no::varchar = #{fileNo})
           AND EXISTS (
               SELECT 1 FROM docs_product_sw s WHERE s.object_id = f.parent_object_id
           )
         LIMIT 1


        SELECT 1 FROM docs_dxf_sub_file
         WHERE parent_object_id = #{objectId}
           AND (#{fileNo} = '*' OR file_no::varchar = #{fileNo})
         LIMIT 1


        SELECT 1 FROM docs_peerreview
         WHERE object_id = #{objectId}
           AND COALESCE(deleted_yn, 'N') = 'N'
           AND (#{fileNo} = '*' OR #{fileNo} = '1')
         LIMIT 1


        SELECT 1 WHERE FALSE


) resource_row

SELECT u.user_cd,
       CASE WHEN COUNT(DISTINCT p.action_cd) FILTER (
           WHERE p.action_cd IN ('LIST', 'DETAIL', 'VIEW')
       ) = 3 THEN 'Y' ELSE 'N' END AS view_yn,
       CASE WHEN COUNT(*) FILTER (
           WHERE p.action_cd = 'DOWNLOAD_ORIGINAL'
       ) > 0 THEN 'Y' ELSE 'N' END AS download_original_yn,
       CASE WHEN COUNT(*) FILTER (
           WHERE p.action_cd = 'PRINT'
       ) > 0 THEN 'Y' ELSE 'N' END AS print_yn
  FROM docs_user u
  LEFT JOIN docs_object_user_permission p
    ON p.object_type = #{request.permissionObjectType}
   AND p.object_id = #{request.objectId}
   AND p.user_cd = u.user_cd
   AND p.allow_yn = 'Y'
 WHERE u.user_cd IN

    #{userCd}

 GROUP BY u.user_cd

mapper.delete:
DELETE FROM docs_object_user_permission
 WHERE object_type = #{permissionObjectType}
   AND object_id = #{objectId}
   AND user_cd = #{userCd}

mapper.select:
SELECT event_id, TO_CHAR(occurred_at AT TIME ZONE 'Asia/Seoul', 'YYYY-MM-DD HH24:MI:SS') AS occurred_at, event_type, action_type, result_cd, reason_cd, result_message, actor_user_cd, actor_user_id, actor_user_nm, object_type, object_id, file_no, request_no, grade_cd, menu_cd, menu_nm, menu_url, action_nm, request_uri, http_method, http_status, duration_ms, client_ip, session_id, correlation_id, detail_json::text AS detail_json FROM docs_access_audit_log WHERE 1 = 1 AND event_type IN ('FILE_ACCESS', 'DOWNLOAD_RESULT', 'PRINT_RESULT', 'ACL_CHANGE')
AND event_type = #{eventType}
AND result_cd = #{resultCd}
AND (COALESCE(actor_user_id, '') ILIKE '%' || #{keyword} || '%' OR COALESCE(actor_user_nm, '') ILIKE '%' || #{keyword} || '%' OR COALESCE(object_id, '') ILIKE '%' || #{keyword} || '%' OR COALESCE(request_no, '') ILIKE '%' || #{keyword} || '%' OR COALESCE(correlation_id, '') ILIKE '%' || #{keyword} || '%')
ORDER BY event_id DESC LIMIT 1000
